function aircraftToken(value){return String(value||'').toUpperCase().replace(/[^A-Z0-9]/g,'').replace(/^(AIRBUS|BOEING|COMAC)/,'').replace(/^B(?=7\d\d)/,'');}
const aircraftAliases={CS300:'a220-300',BD5001A11:'a220-300',BOMBARDIERCS300:'a220-300',A330800:'a330-800neo',A330900:'a330-900neo',E190:'e190',EMBRAER190:'e190',ERJ190:'e190',ATR42500:'atr42',ATR42600:'atr42',ARJ21:'c909',ARJ21700:'c909',C909700:'c909',A380:'a380-800','737MAX8':'b737-max8',EMBRAER195:'e195',EMBRAERE195:'e195',E195:'e195',MCDONNELLDOUGLASMD88:'md88',DHC8400DASH8Q:'dash8-400',DHC8400:'dash8-400',DEHAVILLANDDASH8400:'dash8-400',DEHAVILLANDDASH8:'dash8-400',DASH8Q400:'dash8-400',ATR72600:'atr72'};
// Broad series names do not imply a specific subtype.
function resolveAircraft(value){const key=aircraftToken(value);if(!key)return null;return aircraftCatalog.find(a=>aircraftToken(a.name)===key||a.id===value||a.id===aircraftAliases[key])||null;}
function aircraftIdentity(value){const a=resolveAircraft(value);return a?a.id:'raw:'+String(value||'').trim().toLowerCase().replace(/\s+/g,' ');}
function aircraftLabel(value){return resolveAircraft(value)?.name||String(value||'').trim();}
function ribbonEntry(value){const a=resolveAircraft(value);return a?[a.id,a.name]:null;}
